CREATE OR REPLACE FUNCTION private.mb_caja_venta_manual_entrega()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare r record; available integer;
begin
 if new.estado<>'entregada' or old.estado='entregada' then return new; end if;
 for r in select producto_id,sum(cantidad)::integer cantidad from private.venta_manual_empaque
  where venta_id=new.id group by producto_id order by producto_id loop
  select stock into available from public.producto_simple where id_producto=r.producto_id for update;
  insert into private.inventario_ajuste(operacion_id,producto_id,actor_id,actor_nombre,tipo,
   cantidad_declarada,disponible_anterior,disponible_nuevo,reservado,motivo)
  values(gen_random_uuid(),r.producto_id,new.vendedor_id,new.vendedor_nombre,'egreso',0,
   available,available,private.inventario_reservado(r.producto_id)+r.cantidad,
   'Entrega de venta manual '||new.id::text||': salen '||r.cantidad||' cajas ya reservadas');
 end loop;
 return new;
end $function$

CREATE OR REPLACE FUNCTION private.mb_caja_venta_manual_item()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare box_id bigint; box_stock integer; reserved integer; actor uuid; actor_name text;
begin
 if not exists(select 1 from public.producto_simple where id_producto=new.producto_id and categoria='Mates') then
  return new;
 end if;
 perform pg_advisory_xact_lock(782204,1);
 select producto_id into box_id from private.inventario_ficha where sku='MB-CAJA-MATE';
 if box_id is null then raise exception 'Falta el SKU físico de caja para mate'; end if;
 select stock into box_stock from public.producto_simple where id_producto=box_id for update;
 if box_stock<new.cantidad then raise exception 'Stock insuficiente de cajas para mate'; end if;
 select vendedor_id,vendedor_nombre into actor,actor_name from private.venta_manual where id=new.venta_id;
 reserved:=private.inventario_reservado(box_id);
 update public.producto_simple set stock=stock-new.cantidad where id_producto=box_id;
 update private.inventario_ficha set actualizado_en=now() where producto_id=box_id;
 insert into private.inventario_ajuste(operacion_id,producto_id,actor_id,actor_nombre,tipo,
  cantidad_declarada,disponible_anterior,disponible_nuevo,reservado,motivo)
 values(gen_random_uuid(),box_id,actor,actor_name,'egreso',new.cantidad,box_stock,box_stock-new.cantidad,
  reserved,'Caja para mate en venta manual '||new.venta_id::text||' línea '||new.linea::text);
 insert into private.venta_manual_empaque(venta_id,linea,producto_id,cantidad)
 values(new.venta_id,new.linea,box_id,new.cantidad);
 return new;
end $function$

CREATE OR REPLACE FUNCTION private.mb_sync_caja_mate_trigger()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
begin
 -- The helper writes the box row, which fires this trigger a second time.
 if pg_trigger_depth()>1 then return null; end if;
 if tg_op='DELETE' then
  perform private.mb_sync_caja_mate(old.variante_id);
 else
  perform private.mb_sync_caja_mate(new.variante_id);
  if tg_op='UPDATE' and old.variante_id<>new.variante_id then
   perform private.mb_sync_caja_mate(old.variante_id);
  end if;
 end if;
 return null;
end $function$

CREATE OR REPLACE FUNCTION public.mb_actualizar_envio(p_pedido_id uuid, p_estado text, p_transportista text DEFAULT NULL::text, p_seguimiento text DEFAULT NULL::text)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare o public.pedido;
begin perform pg_advisory_xact_lock(782204, 1);
 select * into o from public.pedido where id=p_pedido_id for update;
 if not found then raise exception 'Pedido inexistente'; end if;
 if not ((o.estado='pagado' and p_estado='preparando') or (o.estado='en_preparacion' and p_estado='enviado') or (o.estado='enviado' and p_estado='entregado')) then raise exception 'Transicion de envio invalida'; end if;
 update public.envio set estado=p_estado,transportista=coalesce(p_transportista,transportista),seguimiento=coalesce(p_seguimiento,seguimiento),actualizado_en=now() where pedido_id=o.id;
 update public.pedido set estado=case p_estado when 'preparando' then 'en_preparacion' else p_estado end where id=o.id;
end $function$

CREATE OR REPLACE FUNCTION public.mb_admin_roles(p_actor_id uuid, p_accion text, p_datos jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare v_id uuid; v_rol text; v_anterior text;
begin
 -- Serialize role changes, then recheck the actor in the same transaction.
 perform pg_catalog.pg_advisory_xact_lock(782204,2);
 if not public.mb_inventario_autorizado(p_actor_id) then
  raise exception 'Solo un administrador puede gestionar el equipo' using errcode='42501';
 end if;
 if p_accion='listar' then
  if jsonb_typeof(p_datos->'ids') is distinct from 'array' or jsonb_array_length(p_datos->'ids')>50 then raise exception 'Lista inválida'; end if;
  return coalesce((select jsonb_object_agg(x.id,public.mb_rol(x.id::uuid)) from jsonb_array_elements_text(p_datos->'ids') x(id)),'{}');
 end if;
 if p_accion is distinct from 'cambiar' then raise exception 'Operación inválida'; end if;
 v_id:=(p_datos->>'usuario_id')::uuid; v_rol:=p_datos->>'rol';
 if v_id is null or v_rol is null or v_rol not in ('cliente','vendedor','administrador') then raise exception 'Rol inválido'; end if;
 if v_id=p_actor_id then raise exception 'Tu propio rol no se modifica desde este panel'; end if;
 v_anterior:=public.mb_rol(v_id);
 if (p_datos->>'anterior') is distinct from v_anterior then raise exception 'El rol cambió. Actualizá la lista antes de guardar'; end if;
 if v_anterior=v_rol then return jsonb_build_object('rol',v_rol); end if;
 if v_anterior='administrador' and v_rol<>'administrador' and
  (select count(*) from private.equipo_inventario where activo)<=1 then raise exception 'Debe quedar al menos un administrador'; end if;
 insert into private.equipo_inventario(usuario_id,activo) values(v_id,v_rol='administrador')
 on conflict(usuario_id) do update set activo=excluded.activo;
 insert into private.equipo_vendedores(usuario_id,activo) values(v_id,v_rol='vendedor')
 on conflict(usuario_id) do update set activo=excluded.activo;
 insert into private.cambio_rol(actor_id,usuario_id,anterior,nuevo) values(p_actor_id,v_id,v_anterior,v_rol);
 return jsonb_build_object('rol',v_rol);
end;
$function$

CREATE OR REPLACE FUNCTION public.mb_asignar_abastecimiento(p_producto_id bigint DEFAULT NULL::bigint, p_pedido_id uuid DEFAULT NULL::uuid)
 RETURNS integer
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare row_demand record; available integer; assigned integer; total integer:=0;
begin
 perform pg_advisory_xact_lock(782204,1);
 for row_demand in
  select d.pedido_id,d.producto_simple_id,d.cantidad_pendiente
  from public.pedido_abastecimiento d join public.pedido p on p.id=d.pedido_id
  where d.cantidad_pendiente>0 and p.estado in ('pagado','en_preparacion')
   and (p_producto_id is null or d.producto_simple_id=p_producto_id)
   and (p_pedido_id is null or d.pedido_id=p_pedido_id)
  order by p.creado_en,d.producto_simple_id for update of d
 loop
  select s.stock into available from public.producto_simple s
   where s.id_producto=row_demand.producto_simple_id for update;
  assigned:=least(coalesce(available,0),row_demand.cantidad_pendiente);
  if assigned<=0 then continue; end if;
  update public.producto_simple set stock=stock-assigned where id_producto=row_demand.producto_simple_id;
  update public.pedido_abastecimiento set cantidad_pendiente=cantidad_pendiente-assigned
   where pedido_id=row_demand.pedido_id and producto_simple_id=row_demand.producto_simple_id;
  insert into public.pedido_stock(pedido_id,producto_simple_id,cantidad)
   values(row_demand.pedido_id,row_demand.producto_simple_id,assigned)
   on conflict(pedido_id,producto_simple_id) do update set cantidad=public.pedido_stock.cantidad+excluded.cantidad;
  insert into public.movimiento_stock(pedido_id,producto_simple_id,cantidad,motivo)
   values(row_demand.pedido_id,row_demand.producto_simple_id,-assigned,'reserva');
  total:=total+assigned;
 end loop;
 return total;
end $function$

CREATE OR REPLACE FUNCTION public.mb_checkout_catalogo(p_token_hash text, p_usuario_id uuid, p_datos jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare c public.carrito; o public.pedido; e public.metodo_envio; d public.direccion;
 v_quote jsonb; v_items jsonb; v_need jsonb; v_reserved jsonb:='[]'; v_unfilled jsonb:='[]';
 v_cost numeric; v_promo boolean; v_minorista_reserva boolean:=p_datos->>'_minorista_reserva'='true'; item jsonb; r record; v_mode text; v_available integer; v_take integer; v_pending integer;
begin
 if p_usuario_id is null then raise exception 'Inicia sesion'; end if;
 if p_token_hash !~ '^[a-f0-9]{64}$' then raise exception 'Sesion invalida'; end if;
 if nullif(p_datos->>'idempotencia','') is null then raise exception 'Falta idempotencia'; end if;
 -- Exactly the same inventory lock used by adjustments, sales, expiration,
 -- payment confirmation and the legacy commerce RPC.
 perform pg_advisory_xact_lock(782204,1);
 perform pg_advisory_xact_lock(hashtextextended(p_usuario_id::text,0));
 select * into o from public.pedido where usuario_id=p_usuario_id and idempotencia=(p_datos->>'idempotencia')::uuid;
 if found then return to_jsonb(o); end if;
 select * into c from public.carrito where token_hash=p_token_hash for update;
 if not found or c.usuario_id is not null and c.usuario_id<>p_usuario_id then raise exception 'Sesion invalida'; end if;
 if c.expira_en<=now() then raise exception 'El carrito vencio'; end if;
 if c.estado='convertido' then
  select * into o from public.pedido where carrito_id=c.id and usuario_id=p_usuario_id;
  if found then return to_jsonb(o); end if;
  raise exception 'Carrito ya confirmado';
 end if;
 if not exists(select 1 from public.carrito_variante where carrito_id=c.id) then raise exception 'Carrito sin variantes'; end if;
 if exists(select 1 from public.carrito_item i join public.producto p on p.id_producto=i.producto_id
   where i.carrito_id=c.id and (not p.activo or p.moneda<>'ARS')) then raise exception 'Producto no disponible'; end if;
 select * into e from public.metodo_envio where codigo=p_datos->>'envio' and (activo or (v_minorista_reserva and codigo='retiro')) for share;
 if not found then raise exception 'Metodo de envio no disponible'; end if;
 perform 1 from public.metodo_pago where codigo=p_datos->>'pago' and activo for share;
 if not found or (p_datos->>'pago'='mercadopago' and not v_minorista_reserva) then raise exception 'Metodo de pago no disponible'; end if;
 if p_datos->>'pago'='efectivo' and e.requiere_direccion then raise exception 'Efectivo solo al retirar'; end if;
 if e.requiere_direccion then
  select * into d from public.direccion where id=(p_datos->>'direccion_id')::uuid and usuario_id=p_usuario_id for share;
  if not found then raise exception 'Direccion no encontrada'; end if;
  if d.pais<>e.pais then raise exception 'Destino fuera de cobertura'; end if;
 end if;
 -- Freeze prices and mapping while taking the order snapshot.
 perform 1 from public.carrito_variante i join public.catalogo_variante cv on cv.id=i.variante_id
  join public.producto p on p.id_producto=cv.producto_id
  where i.carrito_id=c.id order by cv.id for share of cv,p;
 perform 1 from public.catalogo_variante_componente mc join public.carrito_variante i on i.variante_id=mc.variante_id
  where i.carrito_id=c.id order by mc.producto_simple_id for share of mc;
 for r in select i.variante_id,disp.comprable,disp.con_stock from public.carrito_variante i
  join public.mb_catalogo_disponibilidad() disp on disp.variante_id=i.variante_id where i.carrito_id=c.id loop
  if not r.comprable then raise exception 'Variante sin relacion de inventario aprobada'; end if;
  if not r.con_stock then raise exception 'Stock insuficiente'; end if;
 end loop;
 if exists(select 1 from public.carrito_variante i left join public.mb_catalogo_disponibilidad() disp on disp.variante_id=i.variante_id
  where i.carrito_id=c.id and disp.variante_id is null) then raise exception 'Variante sin relacion de inventario aprobada'; end if;
 v_quote:=public.mb_cotizar_catalogo(c.id,p_datos->>'pago');v_items:=v_quote->'items';
 if jsonb_array_length(v_items)=0 then raise exception 'Carrito vacio'; end if;
 if (v_quote->>'subtotal')::numeric<=0 then raise exception 'Precio invalido'; end if;
 select jsonb_agg(to_jsonb(x)) into v_need from (
  select producto_simple_id,sum(cantidad)::integer cantidad from (
   select i.producto_id producto_simple_id,i.cantidad from public.carrito_item i join public.producto p on p.id_producto=i.producto_id where i.carrito_id=c.id and p.tipo='simple'
   union all select ci.id_producto_simple,i.cantidad*ci.cantidad from public.carrito_item i join public.combo_item ci on ci.id_combo=i.producto_id where i.carrito_id=c.id
   union all select mc.producto_simple_id,i.cantidad*mc.cantidad from public.carrito_variante i join public.catalogo_variante_componente mc on mc.variante_id=i.variante_id where i.carrito_id=c.id
  ) n group by producto_simple_id
 ) x;
 if v_need is null then raise exception 'Carrito sin componentes fisicos'; end if;
 for r in select * from jsonb_to_recordset(v_need) as n(producto_simple_id bigint,cantidad integer) order by producto_simple_id loop
  select f.abastecimiento,s.stock into v_mode,v_available from private.inventario_ficha f
   join public.producto_simple s on s.id_producto=f.producto_id
   where f.producto_id=r.producto_simple_id for update of s;
  if not found or v_available is null then raise exception 'Insumo físico no disponible'; end if;
  if v_mode='stock' and v_available<r.cantidad then raise exception 'Stock insuficiente para producto %',r.producto_simple_id; end if;
  v_take:=case when v_mode='a_pedido' then least(v_available,r.cantidad) else r.cantidad end;
  v_pending:=r.cantidad-v_take;
  if v_take>0 then
   update public.producto_simple set stock=stock-v_take where id_producto=r.producto_simple_id and stock>=v_take;
   if not found then raise exception 'Stock insuficiente para producto %',r.producto_simple_id; end if;
   v_reserved:=v_reserved||jsonb_build_array(jsonb_build_object('producto_simple_id',r.producto_simple_id,'cantidad',v_take));
  end if;
  if v_pending>0 then
   v_unfilled:=v_unfilled||jsonb_build_array(jsonb_build_object('producto_simple_id',r.producto_simple_id,'cantidad',v_pending));
  end if;
 end loop;
 -- Shipping promotion only when every catalog line explicitly has free shipping.
 select coalesce(bool_and(cp.envio_gratis is true),false) into v_promo from public.carrito_variante i
  join public.catalogo_variante cv on cv.id=i.variante_id
  join public.catalogo_producto cp on cp.producto_id=cv.producto_id where i.carrito_id=c.id;
 v_cost:=case when not exists(select 1 from public.carrito_item where carrito_id=c.id) and v_promo then 0 else e.costo end;
 update public.carrito set usuario_id=coalesce(usuario_id,p_usuario_id),actualizado_en=now() where id=c.id;
 insert into public.pedido(usuario_id,carrito_id,idempotencia,subtotal,costo_envio,direccion_entrega,moneda)
 values(p_usuario_id,c.id,(p_datos->>'idempotencia')::uuid,(v_quote->>'subtotal')::numeric,v_cost,
  case when e.requiere_direccion then to_jsonb(d)-'usuario_id'-'id'-'creado_en' else jsonb_build_object('retiro',e.nombre) end,'ARS') returning * into o;
 for item in select value from jsonb_array_elements(v_items) loop
  insert into public.pedido_item(pedido_id,producto_id,variante_id,nombre,precio_unitario,cantidad,opciones,personalizacion)
  values(o.id,(item->>'producto_id')::bigint,(item->>'variante_id')::bigint,item->>'nombre',
   (item->>'precio_unitario')::numeric,(item->>'cantidad')::integer,item->'opciones',item->>'personalizacion');
 end loop;
 insert into public.pedido_stock(pedido_id,producto_simple_id,cantidad)
 select o.id,producto_simple_id,cantidad from jsonb_to_recordset(v_reserved) as n(producto_simple_id bigint,cantidad integer);
 insert into public.movimiento_stock(pedido_id,producto_simple_id,cantidad,motivo)
 select o.id,producto_simple_id,-cantidad,'reserva' from jsonb_to_recordset(v_reserved) as n(producto_simple_id bigint,cantidad integer);
 insert into public.pedido_abastecimiento(pedido_id,producto_simple_id,cantidad_solicitada,cantidad_pendiente)
 select o.id,producto_simple_id,cantidad,cantidad from jsonb_to_recordset(v_unfilled) as n(producto_simple_id bigint,cantidad integer);
 insert into public.pago(pedido_id,metodo,importe,moneda) values(o.id,p_datos->>'pago',o.total,'ARS');
 insert into public.envio(pedido_id,metodo) values(o.id,e.codigo);
 update public.carrito set estado='convertido' where id=c.id;
 return to_jsonb(o);
end $function$

CREATE OR REPLACE FUNCTION public.mb_checkout_minorista(p_token_hash text, p_usuario_id uuid, p_datos jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
 c public.carrito; o public.pedido; q public.checkout_cotizacion_envio;
 v_base jsonb; v_line jsonb; v_subtotal numeric(12,2); v_discount numeric(12,2);
 v_carrier numeric(12,2):=0; v_customer_shipping numeric(12,2); v_mode text; v_payment text;
begin
 if p_usuario_id is null then raise exception 'Inicia sesion'; end if;
 if p_token_hash !~ '^[a-f0-9]{64}$' or nullif(p_datos->>'idempotencia','') is null then raise exception 'Sesion o intento invalido'; end if;
 v_mode:=p_datos->>'envio'; v_payment:=p_datos->>'pago';
 if v_mode not in ('retiro','correo_domicilio','correo_sucursal') or v_payment not in ('transferencia','mercadopago')
  then raise exception 'Metodo no disponible'; end if;
 if jsonb_typeof(p_datos->'destinatario') is distinct from 'object' or
  exists(select 1 from unnest(array['nombre','apellido','email','telefono','codigo_postal','provincia','ciudad','calle','numero']) k
    where nullif(trim(p_datos->'destinatario'->>k),'') is null)
  then raise exception 'Destinatario incompleto'; end if;
 perform pg_advisory_xact_lock(782204,1);
 perform pg_advisory_xact_lock(hashtextextended(p_usuario_id::text,0));
 select * into o from public.pedido where usuario_id=p_usuario_id and idempotencia=(p_datos->>'idempotencia')::uuid;
 if found then
  if o.direccion_entrega->'destinatario' is distinct from p_datos->'destinatario'
   or o.direccion_entrega->>'modalidad' is distinct from v_mode
   or (select metodo from public.pago where pedido_id=o.id limit 1) is distinct from v_payment
   then raise exception 'La clave de intento ya corresponde a otro pedido'; end if;
  return to_jsonb(o);
 end if;
 select * into c from public.carrito where token_hash=p_token_hash and (usuario_id is null or usuario_id=p_usuario_id) for update;
 if not found then raise exception 'Carrito inexistente'; end if;
 if c.estado<>'abierto' then raise exception 'Carrito ya confirmado'; end if;
 perform 1 from public.metodo_pago where codigo=v_payment and activo for share;
 if not found then raise exception 'Medio de pago no disponible'; end if;
 perform 1 from public.metodo_envio where codigo=v_mode and activo for share;
 if not found then raise exception 'Entrega no disponible'; end if;
 if v_mode<>'retiro' then
  select * into q from public.checkout_cotizacion_envio where id=(p_datos->>'cotizacion_id')::uuid
   and carrito_id=c.id and usuario_id=p_usuario_id and modalidad=v_mode and destinatario=p_datos->'destinatario'
   and valido_hasta>clock_timestamp() for share;
  if not found then raise exception 'Cotizacion de envio vencida o invalida'; end if;
  v_carrier:=q.costo_transportista;
 end if;
 -- The underlying reservation checks the current mapping, price, stock,
 -- cart ownership and idempotency. Its preliminary commercial snapshot is
 -- replaced below before this transaction commits.
 select * into o from jsonb_populate_record(null::public.pedido,
  public.mb_checkout_catalogo(p_token_hash,p_usuario_id,
   jsonb_build_object('idempotencia',p_datos->>'idempotencia','pago',v_payment,'envio','retiro','_minorista_reserva',true)));
 -- The catalog rows are now locked, so this commercial snapshot cannot race
 -- with a price or mapping edit between quoting and reservation.
 v_base:=public.mb_cotizar_catalogo(c.id,'mercadopago');
 v_subtotal:=(v_base->>'subtotal')::numeric;
 if v_subtotal is null or v_subtotal<=0 then raise exception 'Subtotal invalido'; end if;
 v_discount:=case when v_payment='transferencia' then round(v_subtotal*0.10,2) else 0 end;
 v_customer_shipping:=case when v_subtotal>=80000 then 0 else v_carrier end;
 for v_line in select value from jsonb_array_elements(v_base->'items') loop
  update public.pedido_item set precio_unitario=(v_line->>'precio_unitario')::numeric
   where pedido_id=o.id and variante_id=(v_line->>'variante_id')::bigint;
 end loop;
 update public.pedido set subtotal_mercaderia=v_subtotal,descuento_productos=v_discount,
  subtotal=v_subtotal-v_discount,costo_envio=v_customer_shipping,costo_transportista=v_carrier,
  reserva_hasta=now()+case when v_payment='mercadopago' then interval '1 hour' else interval '24 hours' end,
  direccion_entrega=jsonb_build_object('destinatario',p_datos->'destinatario','modalidad',v_mode,
    'punto',case when v_mode='correo_sucursal' then q.punto else null end)
  where id=o.id returning * into o;
 update public.pago set metodo=v_payment,importe=o.total where pedido_id=o.id;
 update public.envio set metodo=v_mode where pedido_id=o.id;
 return to_jsonb(o);
end $function$

CREATE OR REPLACE FUNCTION public.mb_comercio(p_token_hash text, p_usuario_id uuid, p_accion text, p_datos jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare result jsonb; c public.carrito; v record; q integer; lines jsonb; subtotal numeric; currency text; ready boolean;
begin
 if p_accion='checkout' and exists(select 1 from public.carrito ca join public.carrito_variante i on i.carrito_id=ca.id
  where ca.token_hash=p_token_hash and (ca.usuario_id is null or ca.usuario_id=p_usuario_id)) then
  return public.mb_checkout_catalogo(p_token_hash,p_usuario_id,p_datos);
 end if;
 if p_accion='cantidad' and exists(select 1 from public.producto where id_producto=(p_datos->>'producto_id')::bigint and external_id is not null)
  and (p_datos->>'cantidad')::integer>0 then raise exception 'Selecciona una variante del producto'; end if;
 result:=public.mb_comercio_base(p_token_hash,p_usuario_id,case when p_accion='variante' then 'carrito' else p_accion end,p_datos);
 if p_accion not in ('carrito','cantidad','variante','vincular') or result->>'estado'='convertido' then return result; end if;
 select * into c from public.carrito where token_hash=p_token_hash for update;
 if p_accion='variante' then
  q:=(p_datos->>'cantidad')::integer;
  if q is null or q not between 0 and 99 then raise exception 'Cantidad invalida'; end if;
  if length(coalesce(p_datos->>'personalizacion',''))>1000 then raise exception 'Personalizacion demasiado larga'; end if;
  if q=0 then delete from public.carrito_variante where carrito_id=c.id and variante_id=(p_datos->>'variante_id')::bigint;
  else
   select cv.*,p.moneda into v from public.catalogo_variante cv join public.producto p on p.id_producto=cv.producto_id
   join public.catalogo_producto cp on cp.producto_id=p.id_producto
   where cv.id=(p_datos->>'variante_id')::bigint and cv.vigente and cv.disponible and cv.precio is not null and p.activo and cp.publicado for share of cv,p;
   if not found then raise exception 'Variante no disponible'; end if;
   if v.stock_origen is not null and q>v.stock_origen then raise exception 'Cantidad superior a disponibilidad publicada'; end if;
   if exists(select 1 from public.carrito_item i join public.producto p on p.id_producto=i.producto_id where i.carrito_id=c.id and p.moneda<>v.moneda)
    or exists(select 1 from public.carrito_variante i join public.catalogo_variante cv on cv.id=i.variante_id join public.producto p on p.id_producto=cv.producto_id where i.carrito_id=c.id and p.moneda<>v.moneda)
    then raise exception 'No se pueden mezclar monedas en el carrito'; end if;
   if (select count(*) from public.carrito_variante where carrito_id=c.id)>=100 and not exists(select 1 from public.carrito_variante where carrito_id=c.id and variante_id=v.id) then raise exception 'Carrito lleno'; end if;
   insert into public.carrito_variante(carrito_id,variante_id,cantidad,personalizacion) values(c.id,v.id,q,coalesce(p_datos->>'personalizacion',''))
   on conflict(carrito_id,variante_id) do update set cantidad=excluded.cantidad,
    personalizacion=case when p_datos ? 'personalizacion' then excluded.personalizacion else public.carrito_variante.personalizacion end;
  end if;
 end if;
 if (select count(distinct moneda) from (
  select p.moneda from public.carrito_item i join public.producto p on p.id_producto=i.producto_id where i.carrito_id=c.id
  union all select p.moneda from public.carrito_variante i join public.catalogo_variante cv on cv.id=i.variante_id join public.producto p on p.id_producto=cv.producto_id where i.carrito_id=c.id
 ) currencies)>1 then raise exception 'No se pueden mezclar monedas en el carrito'; end if;
 select coalesce(jsonb_agg(jsonb_build_object('producto_id',p.id_producto::text,'variante_id',cv.id::text,'nombre',p.nombre,
  'opciones',cv.opciones,'personalizacion',i.personalizacion,'cantidad',i.cantidad,'precio',cv.precio,'moneda',p.moneda,
  'activo',p.activo and cp.publicado and cv.vigente and coalesce(cv.disponible,false),'subtotal',cv.precio*i.cantidad)),'[]'),
  coalesce(sum(cv.precio*i.cantidad),0),min(p.moneda) into lines,subtotal,currency
 from public.carrito_variante i join public.catalogo_variante cv on cv.id=i.variante_id
 join public.producto p on p.id_producto=cv.producto_id join public.catalogo_producto cp on cp.producto_id=p.id_producto where i.carrito_id=c.id;
 select bool_and(disp.comprable and disp.con_stock) into ready from public.carrito_variante i
  left join public.mb_catalogo_disponibilidad() disp on disp.variante_id=i.variante_id where i.carrito_id=c.id;
 return result || jsonb_build_object('items',coalesce(result->'items','[]')||lines,'total',coalesce((result->>'total')::numeric,0)+subtotal,
  'moneda',coalesce(currency,(select p.moneda from public.carrito_item i join public.producto p on p.id_producto=i.producto_id where i.carrito_id=c.id limit 1),'ARS'),
  'requiere_confirmacion_catalogo',jsonb_array_length(lines)>0 and not coalesce(ready,false));
end $function$

CREATE OR REPLACE FUNCTION public.mb_comercio_base(p_token_hash text, p_usuario_id uuid, p_accion text, p_datos jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
 c public.carrito; o public.pedido; e public.metodo_envio; d public.direccion;
 r record; v_producto bigint; v_cantidad integer; v_id uuid; v_total numeric(12,2);
 v_result jsonb; v_necesidades jsonb;
begin perform pg_advisory_xact_lock(782204, 1);
 if p_token_hash is null or p_token_hash !~ '^[a-f0-9]{64}$' then raise exception 'Sesion invalida'; end if;
 if p_accion in ('pedidos','checkout','cancelar') and p_usuario_id is null then raise exception 'Inicia sesion'; end if;
 if p_accion='pedidos' then
  return coalesce((select jsonb_agg(to_jsonb(x) order by x.creado_en desc) from (
   select p.*, (select jsonb_agg(to_jsonb(i)) from public.pedido_item i where i.pedido_id=p.id) items,
    (select jsonb_agg(to_jsonb(g)) from public.pago g where g.pedido_id=p.id) pagos,
    (select to_jsonb(s) from public.envio s where s.pedido_id=p.id) envio
   from public.pedido p where p.usuario_id=p_usuario_id order by p.creado_en desc limit 100
  )x),'[]');
 end if;
 if p_accion='cancelar' then
  select * into o from public.pedido where id=(p_datos->>'id')::uuid and usuario_id=p_usuario_id for update;
  if not found then raise exception 'Pedido no encontrado'; end if;
  if o.estado='cancelado' then return to_jsonb(o); end if;
  if o.estado<>'pendiente_pago' then raise exception 'El pedido ya no admite cancelacion automatica'; end if;
  for r in select * from public.pedido_stock where pedido_id=o.id order by producto_simple_id loop
   update public.producto_simple set stock=stock+r.cantidad where id_producto=r.producto_simple_id;
   insert into public.movimiento_stock(pedido_id,producto_simple_id,cantidad,motivo) values(o.id,r.producto_simple_id,r.cantidad,'liberacion');
  end loop;
  update public.pedido set estado='cancelado' where id=o.id returning * into o;
  update public.pago set estado='cancelado' where pedido_id=o.id and estado='pendiente';
  update public.envio set estado='cancelado',actualizado_en=now() where pedido_id=o.id;
  return to_jsonb(o);
 end if;
 if p_accion not in ('carrito','cantidad','checkout','vincular') then raise exception 'Accion invalida'; end if;
 if p_accion='checkout' then
  if nullif(p_datos->>'idempotencia','') is null then raise exception 'Falta idempotencia'; end if;
  perform pg_advisory_xact_lock(hashtextextended(p_usuario_id::text,0));
  select * into o from public.pedido where usuario_id=p_usuario_id and idempotencia=(p_datos->>'idempotencia')::uuid;
  if found then return to_jsonb(o); end if;
 end if;
 insert into public.carrito(token_hash,usuario_id) values(p_token_hash,p_usuario_id) on conflict(token_hash) do nothing;
 select * into c from public.carrito where token_hash=p_token_hash for update;
 if c.usuario_id is not null and c.usuario_id is distinct from p_usuario_id then raise exception 'Sesion invalida'; end if;
 if c.expira_en<=now() then raise exception 'El carrito vencio'; end if;
 if c.estado='convertido' then
  if p_accion='checkout' then
   select * into o from public.pedido where carrito_id=c.id and usuario_id=p_usuario_id;
   return to_jsonb(o);
  elsif p_accion='cantidad' then raise exception 'El carrito ya fue confirmado';
  else return jsonb_build_object('id',c.id,'estado','convertido','items','[]'::jsonb,'total',0); end if;
 end if;
 update public.carrito set usuario_id=coalesce(usuario_id,p_usuario_id),actualizado_en=now() where id=c.id;
 if p_accion='cantidad' then
  v_producto:=(p_datos->>'producto_id')::bigint; v_cantidad:=(p_datos->>'cantidad')::integer;
  if v_cantidad is null or v_cantidad not between 0 and 99 then raise exception 'Cantidad invalida'; end if;
  if v_cantidad=0 then delete from public.carrito_item where carrito_id=c.id and producto_id=v_producto;
  else
   if not exists(select 1 from public.producto where id_producto=v_producto and activo) then raise exception 'Producto no disponible'; end if;
   if (select count(*) from public.carrito_item where carrito_id=c.id)>=100 and not exists(select 1 from public.carrito_item where carrito_id=c.id and producto_id=v_producto) then raise exception 'Carrito lleno'; end if;
   insert into public.carrito_item(carrito_id,producto_id,cantidad) values(c.id,v_producto,v_cantidad)
    on conflict(carrito_id,producto_id) do update set cantidad=excluded.cantidad;
  end if;
 end if;
 if p_accion='checkout' then
  if not exists(select 1 from public.carrito_item where carrito_id=c.id) then raise exception 'Carrito vacio'; end if;
  select * into e from public.metodo_envio where codigo=p_datos->>'envio' and activo for share;
  if not found then raise exception 'Metodo de envio no disponible'; end if;
  perform 1 from public.metodo_pago where codigo=p_datos->>'pago' and activo for share;
  if not found then raise exception 'Metodo de pago no disponible'; end if;
  if p_datos->>'pago'='efectivo' and e.requiere_direccion then raise exception 'Efectivo solo al retirar'; end if;
  if e.requiere_direccion then
   select * into d from public.direccion where id=(p_datos->>'direccion_id')::uuid and usuario_id=p_usuario_id for share;
   if not found then raise exception 'Direccion no encontrada'; end if;
   if d.pais<>e.pais then raise exception 'Destino fuera de cobertura'; end if;
  end if;
  -- Lock prices and composition while taking a historical snapshot.
  perform 1 from public.producto p join public.carrito_item i on i.producto_id=p.id_producto where i.carrito_id=c.id order by p.id_producto for share of p;
  if exists(select 1 from public.carrito_item i join public.producto p on p.id_producto=i.producto_id where i.carrito_id=c.id and not p.activo) then raise exception 'Producto no disponible'; end if;
  perform 1 from public.combo_item ci join public.carrito_item i on i.producto_id=ci.id_combo where i.carrito_id=c.id order by ci.id_combo,ci.id_producto_simple for share of ci;
  if exists(select 1 from public.carrito_item i join public.producto p on p.id_producto=i.producto_id where i.carrito_id=c.id and
   ((p.tipo='simple' and not exists(select 1 from public.producto_simple s where s.id_producto=p.id_producto)) or
    (p.tipo='combo' and (not exists(select 1 from public.combo where id_producto=p.id_producto) or not exists(select 1 from public.combo_item where id_combo=p.id_producto))))) then raise exception 'Producto sin inventario o combo vacio'; end if;
  select jsonb_agg(to_jsonb(n)) into v_necesidades from (
   select producto_simple_id,sum(cantidad)::integer cantidad from (
    select p.id_producto producto_simple_id,i.cantidad from public.carrito_item i join public.producto p on p.id_producto=i.producto_id where i.carrito_id=c.id and p.tipo='simple'
    union all
    select ci.id_producto_simple,ci.cantidad*i.cantidad from public.carrito_item i join public.producto p on p.id_producto=i.producto_id join public.combo_item ci on ci.id_combo=p.id_producto where i.carrito_id=c.id and p.tipo='combo'
   )a group by producto_simple_id
  )n;
  for r in select * from jsonb_to_recordset(v_necesidades) as n(producto_simple_id bigint,cantidad integer) order by producto_simple_id loop
   update public.producto_simple set stock=stock-r.cantidad where id_producto=r.producto_simple_id and stock>=r.cantidad;
   if not found then raise exception 'Stock insuficiente para producto %',r.producto_simple_id; end if;
  end loop;
  select sum(p.precio*i.cantidad) into v_total from public.carrito_item i join public.producto p on p.id_producto=i.producto_id where i.carrito_id=c.id;
  insert into public.pedido(usuario_id,carrito_id,idempotencia,subtotal,costo_envio,direccion_entrega)
   values(p_usuario_id,c.id,(p_datos->>'idempotencia')::uuid,v_total,e.costo,
   case when e.requiere_direccion then to_jsonb(d)-'usuario_id'-'id'-'creado_en' else jsonb_build_object('retiro',e.nombre) end) returning * into o;
  insert into public.pedido_item(pedido_id,producto_id,nombre,precio_unitario,cantidad)
   select o.id,p.id_producto,p.nombre,p.precio,i.cantidad from public.carrito_item i join public.producto p on p.id_producto=i.producto_id where i.carrito_id=c.id;
  insert into public.pedido_stock select o.id,n.producto_simple_id,n.cantidad from jsonb_to_recordset(v_necesidades) as n(producto_simple_id bigint,cantidad integer);
  insert into public.movimiento_stock(pedido_id,producto_simple_id,cantidad,motivo) select o.id,producto_simple_id,-cantidad,'reserva' from public.pedido_stock where pedido_id=o.id;
  insert into public.pago(pedido_id,metodo,importe) values(o.id,p_datos->>'pago',o.total);
  insert into public.envio(pedido_id,metodo) values(o.id,e.codigo);
  update public.carrito set estado='convertido' where id=c.id;
  return to_jsonb(o);
 end if;
 select jsonb_build_object('id',c.id,'estado','abierto','items',coalesce(jsonb_agg(jsonb_build_object('producto_id',p.id_producto::text,'nombre',p.nombre,'cantidad',i.cantidad,'precio',p.precio,'activo',p.activo,'subtotal',p.precio*i.cantidad)),'[]'),'total',coalesce(sum(p.precio*i.cantidad),0)) into v_result
 from public.carrito_item i join public.producto p on p.id_producto=i.producto_id where i.carrito_id=c.id;
 return v_result;
end $function$

CREATE OR REPLACE FUNCTION public.mb_confirmar_pago(p_pago_id uuid, p_referencia text, p_importe numeric, p_moneda text)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare g public.pago; o public.pedido;
begin
 select * into g from public.pago where id=p_pago_id;
 if not found then raise exception 'Pago inexistente'; end if;
 select * into o from public.pedido where id=g.pedido_id for update;
 select * into g from public.pago where id=p_pago_id for update;
 if nullif(trim(p_referencia),'') is null or p_importe is distinct from g.importe or p_moneda is distinct from g.moneda then raise exception 'Pago no coincide'; end if;
 if g.estado='aprobado' and g.referencia_externa=p_referencia then return; end if;
 if g.estado<>'pendiente' or o.estado<>'pendiente_pago' or o.reserva_hasta<=clock_timestamp() then raise exception 'Pago requiere revision manual'; end if;
 update public.pago set estado='aprobado',referencia_externa=p_referencia,confirmado_en=now() where id=g.id;
 update public.pedido set estado='pagado' where id=o.id;
end $function$

CREATE OR REPLACE FUNCTION public.mb_confirmar_transferencia(p_actor_id uuid, p_pedido_id uuid, p_referencia text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare o public.pedido; g public.pago;
begin
 perform pg_advisory_xact_lock(782204,1);
 if not public.mb_inventario_autorizado(p_actor_id) then raise exception 'Solo administracion puede confirmar pagos' using errcode='42501'; end if;
 select * into o from public.pedido where id=p_pedido_id for update;
 if not found then raise exception 'Pedido inexistente'; end if;
 select * into g from public.pago where pedido_id=o.id and metodo='transferencia' for update;
 if not found then raise exception 'No es una transferencia'; end if;
 if exists(select 1 from private.confirmacion_transferencia where pedido_id=o.id) then return to_jsonb(o); end if;
 if o.estado<>'pendiente_pago' or o.reserva_hasta<=clock_timestamp() then raise exception 'Pago requiere revision manual'; end if;
 perform public.mb_confirmar_pago(g.id,p_referencia,g.importe,g.moneda);
 insert into private.confirmacion_transferencia(pedido_id,actor_id,referencia) values(o.id,p_actor_id,p_referencia);
 select * into o from public.pedido where id=p_pedido_id;
 return to_jsonb(o);
end $function$

CREATE OR REPLACE FUNCTION public.mb_cotizar_catalogo(p_carrito_id uuid, p_pago text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO ''
AS $function$
declare r record; items jsonb:='[]'; total numeric:=0; qty integer;
begin
 qty:=public.mb_cantidad_promo(p_carrito_id);
 for r in select i.producto_id,p.nombre,p.moneda,p.precio,i.cantidad from public.carrito_item i
  join public.producto p on p.id_producto=i.producto_id where i.carrito_id=p_carrito_id order by i.producto_id loop
  if r.moneda<>'ARS' or r.precio is null then raise exception 'Producto sin precio ARS'; end if;
  items:=items||jsonb_build_array(jsonb_build_object('producto_id',r.producto_id,'variante_id',null,
   'nombre',r.nombre,'cantidad',r.cantidad,'precio_unitario',r.precio,'opciones',null,'personalizacion',null));
  total:=total+r.cantidad*r.precio;
 end loop;
 for r in select i.variante_id,i.cantidad,i.personalizacion,cv.producto_id,cv.opciones,cv.precio,
   cv.vigente,cv.disponible,p.nombre,p.moneda,p.activo,cp.publicado
  from public.carrito_variante i join public.catalogo_variante cv on cv.id=i.variante_id
  join public.producto p on p.id_producto=cv.producto_id join public.catalogo_producto cp on cp.producto_id=p.id_producto
  where i.carrito_id=p_carrito_id order by i.variante_id loop
  if r.moneda<>'ARS' or not r.activo or not r.publicado or not r.vigente or not r.disponible or r.precio is null
   then raise exception 'Variante no disponible'; end if;
  r.precio:=public.mb_precio_variante(r.variante_id,p_pago,qty);
  items:=items||jsonb_build_array(jsonb_build_object('producto_id',r.producto_id,'variante_id',r.variante_id,
   'nombre',r.nombre,'cantidad',r.cantidad,'precio_unitario',r.precio,'opciones',r.opciones,'personalizacion',r.personalizacion));
  total:=total+r.cantidad*r.precio;
 end loop;
 return jsonb_build_object('items',items,'subtotal',total,'moneda','ARS');
end $function$

CREATE OR REPLACE FUNCTION public.mb_estado_preparacion_pedido()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
begin
 if new.estado='pagado' and old.estado='pendiente_pago' then
  update public.pedido_preparacion set estado='pendiente_preparar',actualizado_en=now()
   where pedido_id=new.id and estado='pendiente_pago';
  perform public.mb_asignar_abastecimiento(null,new.id);
 elsif new.estado='cancelado' then
  update public.pedido_preparacion set estado='cancelado',actualizado_en=now()
   where pedido_id=new.id and estado='pendiente_pago';
 elsif new.estado='enviado' then
  update public.pedido_preparacion set estado='despachado',actualizado_en=now()
   where pedido_id=new.id and estado='listo_despachar';
 elsif new.estado='entregado' then
  update public.pedido_preparacion set estado='entregado',actualizado_en=now()
   where pedido_id=new.id and estado='despachado';
 end if;
 return new;
end $function$

CREATE OR REPLACE FUNCTION public.mb_expirar_reservas()
 RETURNS integer
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare r record; n integer:=0;
begin
 perform pg_advisory_xact_lock(782204,1);
 for r in select id,usuario_id from public.pedido where estado='pendiente_pago' and reserva_hasta<=now()
  order by reserva_hasta limit 100 for update skip locked loop
  perform public.mb_comercio(repeat('0',64),r.usuario_id,'cancelar',jsonb_build_object('id',r.id));
  update public.pedido set estado='expirado' where id=r.id;
  n:=n+1;
 end loop;
 return n;
end $function$

CREATE OR REPLACE FUNCTION public.mb_importar_catalogo(p jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare pid bigint; nuevo boolean; r jsonb; cid bigint; parentid bigint; ids bigint[]:='{}';
begin
 perform pg_advisory_xact_lock(hashtextextended('matebreak_catalog_import',0));
 if nullif(p->>'external_id','') is null or nullif(p->>'nombre','') is null
 or p->>'source_url' not like 'https://matebreak.com.ar/productos/%' then raise exception 'Producto invalido'; end if;
 select id_producto into pid from public.producto where external_id=p->>'external_id';
 nuevo:=pid is null;
 if nuevo then
  insert into public.producto(nombre,descripcion,precio,tipo,activo,source_url,external_id,slug,moneda)
  values(p->>'nombre',p->>'descripcion',(p->>'precio')::numeric,p->>'tipo',
   (p->>'precio') is not null,p->>'source_url',p->>'external_id',p->>'slug',p->>'moneda') returning id_producto into pid;
 else
  update public.producto set nombre=p->>'nombre',descripcion=p->>'descripcion',precio=(p->>'precio')::numeric,
   activo=(p->>'precio') is not null,source_url=p->>'source_url',slug=p->>'slug',moneda=p->>'moneda',actualizado_en=now()
   where id_producto=pid;
  if (select tipo from public.producto where id_producto=pid)<>p->>'tipo' then raise exception 'Cambio de tipo requiere revision'; end if;
 end if;
 if p->>'tipo'='simple' then
  insert into public.producto_simple(id_producto,material,stock) values(pid,p->>'material',null) on conflict(id_producto) do nothing;
 else insert into public.combo(id_producto) values(pid) on conflict do nothing; end if;
 insert into public.catalogo_producto(producto_id,disponible,precio_original,precio_transferencia,descuento,cuotas,envio_gratis,destacado,
  descripcion_origen,personalizacion,atributos,source_hash,extraido_en,publicado)
 values(pid,(p->>'disponible')::boolean,(p->>'precio_original')::numeric,(p->>'precio_transferencia')::numeric,
  (p->>'descuento')::numeric,p->'cuotas',(p->>'envio_gratis')::boolean,(p->>'destacado')::boolean,
  p->>'descripcion_html',p->'personalizacion',p->'atributos',p->>'source_hash',(p->>'extraido_en')::timestamptz,true)
 on conflict(producto_id) do update set disponible=excluded.disponible,precio_original=excluded.precio_original,
  precio_transferencia=excluded.precio_transferencia,descuento=excluded.descuento,cuotas=excluded.cuotas,
  envio_gratis=excluded.envio_gratis,destacado=excluded.destacado,descripcion_origen=excluded.descripcion_origen,
  personalizacion=excluded.personalizacion,atributos=excluded.atributos,source_hash=excluded.source_hash,
  extraido_en=excluded.extraido_en,importado_en=now(),publicado=true;
 -- Replace only imported descriptive relations; preserve products, assets and cart lines.
 delete from public.catalogo_producto_categoria where producto_id=pid;
 delete from public.catalogo_opcion where producto_id=pid;
 delete from public.catalogo_promocion where producto_id=pid;
 parentid:=null;
 for r in select * from jsonb_array_elements(p->'categorias') loop
  insert into public.catalogo_categoria(nombre,slug,source_url,padre_id)
   values(r->>'nombre',r->>'slug',r->>'source_url',parentid)
   on conflict(source_url) do update set nombre=excluded.nombre returning id into cid;
  insert into public.catalogo_producto_categoria values(pid,cid) on conflict do nothing;
  parentid:=cid;
 end loop;
 for r in select * from jsonb_array_elements(p->'opciones') loop
  insert into public.catalogo_opcion values(pid,(r->>'posicion')::integer,r->>'nombre',r->'valores')
  on conflict(producto_id,posicion) do update set nombre=excluded.nombre,valores=excluded.valores;
 end loop;
 update public.catalogo_variante set vigente=false where producto_id=pid;
 for r in select * from jsonb_array_elements(p->'variantes') loop
  insert into public.catalogo_variante(producto_id,external_id,opciones,precio,precio_original,precio_transferencia,cuotas,disponible,stock_origen,sku,imagen_origen)
  values(pid,r->>'external_id',r->'opciones',(r->>'precio')::numeric,(r->>'precio_original')::numeric,
   (r->>'precio_transferencia')::numeric,r->'cuotas',(r->>'disponible')::boolean,(r->>'stock')::integer,r->>'sku',r->>'imagen')
  on conflict(external_id) do update set opciones=excluded.opciones,precio=excluded.precio,precio_original=excluded.precio_original,
   precio_transferencia=excluded.precio_transferencia,cuotas=excluded.cuotas,disponible=excluded.disponible,
   stock_origen=excluded.stock_origen,sku=excluded.sku,imagen_origen=excluded.imagen_origen,vigente=true;
 end loop;
 update public.catalogo_imagen set vigente=false where producto_id=pid;
 for r in select * from jsonb_array_elements(p->'imagenes') loop
  insert into public.catalogo_asset values(r->>'sha256',r->>'storage_path',r->>'mime_type',(r->>'bytes')::bigint) on conflict do nothing;
  insert into public.catalogo_imagen values(pid,r->>'source_url',r->>'sha256',(r->>'posicion')::integer,r->>'rol',r->>'alt',true)
  on conflict(producto_id,source_url) do update set asset_hash=excluded.asset_hash,posicion=excluded.posicion,rol=excluded.rol,alt=excluded.alt,vigente=true;
 end loop;
 for r in select * from jsonb_array_elements(p->'promociones') loop
  insert into public.catalogo_promocion values(pid,r#>>'{}') on conflict do nothing;
 end loop;
 for r in select * from jsonb_array_elements(p->'componentes') loop
  insert into public.catalogo_componente(combo_id,evidencia,source_url) values(pid,r->>'evidencia',r->>'source_url') on conflict do nothing;
 end loop;
 for r in select * from jsonb_array_elements(p->'revision') loop
  insert into public.catalogo_revision(producto_id,motivo) values(pid,r#>>'{}') on conflict do nothing;
 end loop;
 return jsonb_build_object('id',pid::text,'creado',nuevo);
end $function$

CREATE OR REPLACE FUNCTION public.mb_inventario(p_usuario_id uuid, p_accion text, p_datos jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
 f private.inventario_ficha; a private.inventario_ajuste;
 v_stock integer; v_reservado integer; v_nuevo integer; v_cantidad integer;
 v_id bigint; v_operacion uuid; v_tipo text; v_motivo text; v_result jsonb;
begin
 if not public.mb_inventario_autorizado(p_usuario_id) then
  raise exception using errcode='42501',message='Acceso exclusivo del equipo de inventario';
 end if;
 if p_accion='listar' then
  select coalesce(jsonb_agg(to_jsonb(x) order by x.nombre),'[]') into v_result from (
   select fi.producto_id::text id,fi.sku,p.nombre,s.material,s.categoria,s.diseno,
    s.stock disponible,private.inventario_reservado(fi.producto_id) reservado,
    s.stock+private.inventario_reservado(fi.producto_id) fisico,
    fi.abastecimiento,fi.aproximado,fi.minimo,fi.notas,fi.actualizado_en,
    p.activo publicado,p.precio
   from private.inventario_ficha fi join public.producto_simple s on s.id_producto=fi.producto_id
   join public.producto p on p.id_producto=fi.producto_id
  )x;
  return v_result;
 end if;
 if p_accion='historial' then
  v_id:=nullif(p_datos->>'producto_id','')::bigint;
  return coalesce((select jsonb_agg(to_jsonb(x) order by x.creado_en desc) from (
   select h.*,p.nombre from (
    select hist.id,hist.producto_id,hist.tipo,hist.diferencia,hist.disponible_anterior,hist.disponible_nuevo,hist.reservado,hist.motivo,hist.actor_nombre,hist.creado_en,null::uuid pedido_id
    from private.inventario_ajuste hist where v_id is null or hist.producto_id=v_id
    union all
    select m.id,m.producto_simple_id,m.motivo,m.cantidad,null::integer,null::integer,null::integer,
     case m.motivo when 'reserva' then 'Reserva de pedido' else 'Cancelacion o vencimiento de pedido' end,
     'Sistema de pedidos',m.creado_en,m.pedido_id
    from public.movimiento_stock m where v_id is null or m.producto_simple_id=v_id
   )h join public.producto p on p.id_producto=h.producto_id order by h.creado_en desc limit 200
  )x),'[]');
 end if;
 if p_accion not in ('ajustar','configurar') then raise exception 'Operacion de inventario invalida'; end if;
 -- Same first lock as checkout/cancellation/shipment: a physical recount must
 -- not race an order reservation or a shipment leaving the warehouse.
 perform pg_advisory_xact_lock(782204, 1);
 v_id:=(p_datos->>'producto_id')::bigint;
 select * into f from private.inventario_ficha where producto_id=v_id for update;
 if not found then raise exception 'Articulo no encontrado'; end if;
 if p_accion='configurar' then
  if p_datos->>'abastecimiento' not in ('stock','a_pedido') or
   (p_datos->>'minimo')::integer not between 0 and 1000000 or p_datos->>'notas' is null then raise exception 'Configuracion invalida'; end if;
  update private.inventario_ficha set abastecimiento=p_datos->>'abastecimiento',minimo=(p_datos->>'minimo')::integer,
   notas=p_datos->>'notas',actualizado_en=clock_timestamp() where producto_id=v_id returning * into f;
  return to_jsonb(f);
 end if;
 v_tipo:=p_datos->>'tipo'; v_cantidad:=(p_datos->>'cantidad')::integer;
 v_operacion:=(p_datos->>'idempotencia')::uuid; v_motivo:=trim(p_datos->>'motivo');
 if v_operacion is null or v_tipo is null or v_tipo not in ('ingreso','egreso','conteo') or v_cantidad is null or
  v_cantidad not between 0 and 1000000 or (v_tipo<>'conteo' and v_cantidad=0) or
  v_motivo is null or length(v_motivo) not between 3 and 500 then raise exception 'Indica cantidad, tipo y motivo validos'; end if;
 select * into a from private.inventario_ajuste where operacion_id=v_operacion;
 if found then
  if a.actor_id is distinct from p_usuario_id or a.producto_id<>v_id or a.tipo<>v_tipo or
   a.cantidad_declarada<>v_cantidad or a.motivo<>v_motivo then raise exception 'Esta operacion ya se uso para otro ajuste'; end if;
  return to_jsonb(a);
 end if;
 select stock into v_stock from public.producto_simple where id_producto=v_id for update;
 v_reservado:=private.inventario_reservado(v_id);
 if v_stock is distinct from (p_datos->>'disponible_esperado')::integer or
  v_reservado is distinct from (p_datos->>'reservado_esperado')::integer then
  raise exception 'El stock cambio. Actualiza el inventario antes de guardar';
 end if;
 v_nuevo:=case v_tipo when 'ingreso' then v_stock+v_cantidad when 'egreso' then v_stock-v_cantidad else v_cantidad-v_reservado end;
 if v_nuevo<0 then raise exception 'No podes descontar las unidades reservadas para pedidos'; end if;
 update public.producto_simple set stock=v_nuevo where id_producto=v_id;
 update private.inventario_ficha set aproximado=case when v_tipo='conteo' then false else aproximado end,
  actualizado_en=clock_timestamp() where producto_id=v_id;
 insert into private.inventario_ajuste(operacion_id,producto_id,actor_id,actor_nombre,tipo,cantidad_declarada,
  disponible_anterior,disponible_nuevo,reservado,motivo)
 values(v_operacion,v_id,p_usuario_id,coalesce(nullif((select nombre from public.perfil where id=p_usuario_id),''),p_usuario_id::text),
  v_tipo,v_cantidad,v_stock,v_nuevo,v_reservado,v_motivo) returning * into a;
 return to_jsonb(a);
end $function$

CREATE OR REPLACE FUNCTION public.mb_preparacion(p_actor_id uuid, p_accion text, p_datos jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare job public.pedido_preparacion; order_state text; old_state text; next_state text; note text; result jsonb;
begin
 if not public.mb_inventario_autorizado(p_actor_id) then
  raise exception using errcode='42501',message='Acceso exclusivo del equipo de inventario'; end if;
 if p_accion='listar' then
  select jsonb_build_object(
   'resumen',coalesce((select jsonb_agg(to_jsonb(x) order by x.sku) from (
    select f.sku,p.nombre,sum(j.cantidad)::integer cantidad
    from public.pedido_preparacion j join private.inventario_ficha f on f.producto_id=j.producto_simple_id
    join public.producto p on p.id_producto=j.producto_simple_id
    where j.estado in ('pendiente_preparar','enviado_grabar') group by f.sku,p.nombre
   )x),'[]'),
   'items',coalesce((select jsonb_agg(to_jsonb(x) order by x.creado_en,x.id) from (
    select j.id,j.pedido_id,j.producto_simple_id,j.cantidad,j.estado,j.actualizado_en,
     f.sku,p.nombre base_fisica,pi.nombre producto_vendido,pi.opciones,pi.personalizacion,
     o.creado_en,coalesce(d.cantidad_pendiente,0) pendiente_abastecimiento
    from public.pedido_preparacion j join public.pedido_item pi on pi.id=j.pedido_item_id
    join public.pedido o on o.id=j.pedido_id join private.inventario_ficha f on f.producto_id=j.producto_simple_id
    join public.producto p on p.id_producto=j.producto_simple_id
    left join public.pedido_abastecimiento d on d.pedido_id=j.pedido_id and d.producto_simple_id=j.producto_simple_id
    where j.estado not in ('pendiente_pago','entregado','cancelado')
    order by o.creado_en desc limit 200
   )x),'[]')) into result;
  return result;
 end if;
 if p_accion<>'avanzar' then raise exception 'Accion de preparacion invalida'; end if;
 perform pg_advisory_xact_lock(782204,1);
 select * into job from public.pedido_preparacion where id=(p_datos->>'id')::uuid for update;
 if not found then raise exception 'Preparacion inexistente'; end if;
 select estado into order_state from public.pedido where id=job.pedido_id for share;
 if order_state not in ('pagado','en_preparacion') then raise exception 'Pedido no pagado o ya despachado'; end if;
 next_state:=p_datos->>'estado'; note:=trim(coalesce(p_datos->>'nota',''));
 if length(note)>500 or not ((job.estado='pendiente_preparar' and next_state='enviado_grabar')
  or (job.estado='enviado_grabar' and next_state='grabado_recibido')
  or (job.estado='grabado_recibido' and next_state='listo_despachar'))
  then raise exception 'Transicion de grabado invalida'; end if;
 if job.estado='pendiente_preparar' and exists(select 1 from public.pedido_abastecimiento d
  where d.pedido_id=job.pedido_id and d.producto_simple_id=job.producto_simple_id and d.cantidad_pendiente>0)
  then raise exception 'Falta recibir la pieza fisica'; end if;
 old_state:=job.estado;
 update public.pedido_preparacion set estado=next_state,actualizado_en=now() where id=job.id returning * into job;
 insert into private.preparacion_evento(preparacion_id,actor_id,estado_anterior,estado_nuevo,nota)
 values(job.id,p_actor_id,old_state,next_state,note);
 return to_jsonb(job);
end $function$

CREATE OR REPLACE FUNCTION public.mb_registrar_recepcion(p_actor_id uuid, p_datos jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare receipt private.inventario_recepcion; adjustment private.inventario_ajuste;
 v_product_id bigint; v_operation uuid; v_quantity integer; v_cost numeric(14,2);
 v_date date; v_provider text; v_reason text; v_before integer; v_reserved integer; v_allocated integer;
begin
 if not public.mb_inventario_autorizado(p_actor_id) then
  raise exception using errcode='42501',message='Acceso exclusivo del equipo de inventario'; end if;
 v_operation:=(p_datos->>'idempotencia')::uuid;
 v_product_id:=(p_datos->>'producto_id')::bigint;
 v_quantity:=(p_datos->>'cantidad')::integer;
 v_cost:=(p_datos->>'costo_unitario')::numeric(14,2);
 v_date:=(p_datos->>'fecha')::date;
 v_provider:=nullif(trim(coalesce(p_datos->>'proveedor','')),'');
 v_reason:=trim(coalesce(p_datos->>'motivo',''));
 if v_operation is null or v_product_id is null or v_quantity is null or v_quantity not between 1 and 1000000
  or v_cost is null or v_cost<0 or v_date is null or v_date>current_date or v_date<date '2000-01-01'
  or length(v_reason) not between 3 and 500 or length(coalesce(v_provider,''))>150
  then raise exception 'Recepcion invalida'; end if;
 perform pg_advisory_xact_lock(782204,1);
 select * into receipt from private.inventario_recepcion where operacion_id=v_operation;
 if found then
  if receipt.actor_id<>p_actor_id or receipt.producto_id<>v_product_id or receipt.cantidad<>v_quantity
   or receipt.costo_unitario<>v_cost or receipt.fecha<>v_date or receipt.proveedor is distinct from v_provider
   or receipt.motivo<>v_reason then raise exception 'Esta recepcion ya se uso con otros datos'; end if;
  return to_jsonb(receipt);
 end if;
 perform 1 from private.inventario_ficha where producto_id=v_product_id for update;
 if not found then raise exception 'Articulo no encontrado'; end if;
 select stock into v_before from public.producto_simple where id_producto=v_product_id for update;
 if v_before is null then raise exception 'Primero confirma el stock fisico del articulo'; end if;
 v_reserved:=private.inventario_reservado(v_product_id);
 if v_before is distinct from (p_datos->>'disponible_esperado')::integer
  or v_reserved is distinct from (p_datos->>'reservado_esperado')::integer
  then raise exception 'El stock cambio. Actualiza el inventario antes de guardar'; end if;
 update public.producto_simple set stock=stock+v_quantity where id_producto=v_product_id;
 update private.inventario_ficha set actualizado_en=clock_timestamp() where producto_id=v_product_id;
 insert into private.inventario_ajuste(operacion_id,producto_id,actor_id,actor_nombre,tipo,cantidad_declarada,
  disponible_anterior,disponible_nuevo,reservado,motivo)
 values(v_operation,v_product_id,p_actor_id,
  coalesce(nullif((select nombre from public.perfil where id=p_actor_id),''),p_actor_id::text),
  'ingreso',v_quantity,v_before,v_before+v_quantity,v_reserved,v_reason) returning * into adjustment;
 insert into private.inventario_recepcion(operacion_id,ajuste_id,producto_id,cantidad,costo_unitario,fecha,
  actor_id,actor_nombre,proveedor,motivo)
 values(v_operation,adjustment.id,v_product_id,v_quantity,v_cost,v_date,p_actor_id,adjustment.actor_nombre,v_provider,v_reason)
 returning * into receipt;
 v_allocated:=public.mb_asignar_abastecimiento(v_product_id,null);
 return to_jsonb(receipt)||jsonb_build_object('asignado_a_pedidos',v_allocated);
end $function$

CREATE OR REPLACE FUNCTION public.mb_validar_despacho()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
begin
 if new.estado in ('enviado','entregado') and old.estado is distinct from new.estado then
  if exists(select 1 from public.pedido_abastecimiento d where d.pedido_id=new.id and d.cantidad_pendiente>0)
   then raise exception 'Pedido con componentes pendientes de abastecimiento'; end if;
  if exists(select 1 from public.pedido_preparacion p where p.pedido_id=new.id and p.estado<>'listo_despachar'
   and new.estado='enviado') then raise exception 'Pedido con grabados pendientes'; end if;
 end if;
 return new;
end $function$

CREATE OR REPLACE FUNCTION public.mb_validar_transicion_pedido()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
begin
 if new.estado is not distinct from old.estado then return new; end if;
 if not (
  (old.estado='pendiente_pago' and new.estado in ('pagado','cancelado')) or
  (old.estado='cancelado' and new.estado='expirado' and old.reserva_hasta<=clock_timestamp()) or
  (old.estado='pagado' and new.estado='en_preparacion') or
  (old.estado='en_preparacion' and new.estado='enviado') or
  (old.estado='enviado' and new.estado='entregado')
 ) then raise exception 'Transicion de pedido invalida: % -> %',old.estado,new.estado; end if;
 return new;
end $function$

CREATE OR REPLACE FUNCTION public.mb_ventas(p_usuario_id uuid, p_accion text, p_datos jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare v private.venta_manual; r record; item jsonb; v_items jsonb:='[]'; v_total numeric:=0;
 v_operacion uuid; v_estado text; v_nombre text; v_stock integer; v_reservado integer; v_linea integer:=0;
 v_id bigint; v_qty integer; v_precio numeric; v_grabado text;
begin
 if p_usuario_id is null or public.mb_rol(p_usuario_id)<>'vendedor' then
  raise exception using errcode='42501',message='Esta operacion requiere una cuenta de vendedor';
 end if;
 if p_accion='productos' then
  return coalesce((select jsonb_agg(to_jsonb(x) order by x.nombre) from (
   select f.producto_id::text id,f.sku,p.nombre,p.precio from private.inventario_ficha f
   join public.producto p on p.id_producto=f.producto_id
  )x),'[]');
 end if;
 if p_accion='listar' then
  return coalesce((select jsonb_agg(to_jsonb(x) order by (x.estado='entregada'),x.creado_en desc) from (
   select vm.id,vm.cliente,vm.telefono,vm.estado,vm.total,vm.moneda,vm.metodo_pago,vm.notas,vm.creado_en,
   (select jsonb_agg(jsonb_build_object('nombre',vi.nombre,'cantidad',vi.cantidad,'precio_unitario',vi.precio_unitario,'personalizacion',vi.personalizacion) order by vi.linea)
    from private.venta_manual_item vi where vi.venta_id=vm.id) items
   from private.venta_manual vm where vm.vendedor_id=p_usuario_id order by (vm.estado='entregada'),vm.creado_en desc limit 200
  )x),'[]');
 end if;
 perform pg_advisory_xact_lock(782204, 1);
 if p_accion='estado' then
  select * into v from private.venta_manual where id=(p_datos->>'id')::uuid and vendedor_id=p_usuario_id for update;
  if not found then raise exception 'Venta no encontrada'; end if;
  v_estado:=p_datos->>'estado';
  if v_estado is null or v_estado not in ('por_entregar','entregada') then raise exception 'Estado invalido'; end if;
  if v.estado=v_estado then return jsonb_build_object('id',v.id,'estado',v.estado); end if;
  if not ((v.estado='por_grabar' and v_estado='por_entregar') or (v.estado='por_entregar' and v_estado='entregada')) then raise exception 'La venta debe pasar de grabado a entrega, y luego a entregada'; end if;
  if v_estado='entregada' then
   for r in select vi.producto_id,sum(vi.cantidad)::integer cantidad from private.venta_manual_item vi where vi.venta_id=v.id group by vi.producto_id order by vi.producto_id loop
    select stock into v_stock from public.producto_simple where id_producto=r.producto_id for update;
    v_reservado:=private.inventario_reservado(r.producto_id);
    insert into private.inventario_ajuste(operacion_id,producto_id,actor_id,actor_nombre,tipo,cantidad_declarada,disponible_anterior,disponible_nuevo,reservado,motivo)
     values(gen_random_uuid(),r.producto_id,p_usuario_id,v.vendedor_nombre,'egreso',0,v_stock,v_stock,v_reservado,
      'Entrega de venta '||v.id::text||': salen '||r.cantidad||' unidades ya reservadas');
   end loop;
  end if;
  update private.venta_manual set estado=v_estado,actualizado_en=now(),entregada_en=case when v_estado='entregada' then now() else null end where id=v.id;
  insert into private.venta_manual_evento(venta_id,actor_id,estado) values(v.id,p_usuario_id,v_estado);
  return jsonb_build_object('id',v.id,'estado',v_estado);
 end if;
 if p_accion is distinct from 'registrar' then raise exception 'Operacion invalida'; end if;
 v_operacion:=(p_datos->>'idempotencia')::uuid;
 if v_operacion is null then raise exception 'Falta identificador de la venta'; end if;
 select * into v from private.venta_manual where operacion_id=v_operacion;
 if found then
  if v.vendedor_id is distinct from p_usuario_id or v.solicitud<>p_datos then raise exception 'Ese identificador ya corresponde a otra venta'; end if;
  return jsonb_build_object('id',v.id,'estado',v.estado,'total',v.total);
 end if;
 v_estado:=p_datos->>'estado';
 if v_estado is null or v_estado not in ('por_grabar','por_entregar','entregada') or
  p_datos->>'cliente' is null or length(trim(p_datos->>'cliente')) not between 2 and 150 or
  p_datos->>'metodo_pago' is null or p_datos->>'metodo_pago' not in ('efectivo','transferencia','tarjeta','otro') or
  jsonb_typeof(p_datos->'items') is distinct from 'array' then raise exception 'Revisa los datos de la venta'; end if;
 if jsonb_array_length(p_datos->'items') not between 1 and 50 then raise exception 'Agrega entre 1 y 50 lineas'; end if;
 for item in select value from jsonb_array_elements(p_datos->'items') loop
  if coalesce(item->>'cantidad','') !~ '^[0-9]+$' then raise exception 'Cantidad invalida'; end if;
  v_id:=(item->>'producto_id')::bigint; v_qty:=(item->>'cantidad')::integer; v_precio:=(item->>'precio_unitario')::numeric;
  v_grabado:=coalesce(trim(item->>'personalizacion'),'');
  if v_id is null or v_qty not between 1 and 10000 or v_precio is null or v_precio<=0 or v_precio>1000000 or
   v_precio<>round(v_precio,2) or length(v_grabado)>500 then raise exception 'Producto, cantidad o precio invalido'; end if;
  select p.nombre into v_nombre from private.inventario_ficha f join public.producto p on p.id_producto=f.producto_id where f.producto_id=v_id;
  if not found then raise exception 'Producto no encontrado'; end if;
  v_items:=v_items||jsonb_build_array(jsonb_build_object('producto_id',v_id,'cantidad',v_qty,'precio_unitario',v_precio,'nombre',v_nombre,'personalizacion',v_grabado));
  v_total:=v_total+v_qty*v_precio;
 end loop;
 if v_estado='por_grabar' and not exists(select 1 from jsonb_array_elements(v_items) x where x->>'personalizacion'<>'') then raise exception 'Indica el grabado solicitado'; end if;
 v_nombre:=coalesce(nullif((select nombre from public.perfil where id=p_usuario_id),''),'Vendedor '||p_usuario_id::text);
 for r in select (x->>'producto_id')::bigint producto_id,sum((x->>'cantidad')::integer)::integer cantidad from jsonb_array_elements(v_items)x group by 1 order by 1 loop
  select stock into v_stock from public.producto_simple where id_producto=r.producto_id for update;
  if v_stock<r.cantidad then raise exception 'Stock insuficiente para registrar esta venta'; end if;
  v_reservado:=private.inventario_reservado(r.producto_id);
  update public.producto_simple set stock=stock-r.cantidad where id_producto=r.producto_id;
  update private.inventario_ficha set actualizado_en=now() where producto_id=r.producto_id;
  insert into private.inventario_ajuste(operacion_id,producto_id,actor_id,actor_nombre,tipo,cantidad_declarada,disponible_anterior,disponible_nuevo,reservado,motivo)
   values(gen_random_uuid(),r.producto_id,p_usuario_id,v_nombre,'egreso',r.cantidad,v_stock,v_stock-r.cantidad,v_reservado,
    case when v_estado='entregada' then 'Venta entregada ' else 'Reserva de venta ' end||v_operacion::text);
 end loop;
 insert into private.venta_manual(operacion_id,vendedor_id,vendedor_nombre,cliente,telefono,estado,metodo_pago,total,notas,solicitud,entregada_en)
  values(v_operacion,p_usuario_id,v_nombre,trim(p_datos->>'cliente'),coalesce(p_datos->>'telefono',''),v_estado,p_datos->>'metodo_pago',v_total,
   coalesce(p_datos->>'notas',''),p_datos,case when v_estado='entregada' then now() else null end) returning * into v;
 for item in select value from jsonb_array_elements(v_items) loop
  v_linea:=v_linea+1;
  insert into private.venta_manual_item(venta_id,linea,producto_id,nombre,cantidad,precio_unitario,personalizacion)
  values(v.id,v_linea,(item->>'producto_id')::bigint,item->>'nombre',(item->>'cantidad')::integer,(item->>'precio_unitario')::numeric,item->>'personalizacion');
 end loop;
 insert into private.venta_manual_evento(venta_id,actor_id,estado) values(v.id,p_usuario_id,v_estado);
 return jsonb_build_object('id',v.id,'estado',v.estado,'total',v.total);
end $function$

CREATE OR REPLACE FUNCTION public.rls_auto_enable()
 RETURNS event_trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE
  cmd record;
BEGIN
  FOR cmd IN
    SELECT *
    FROM pg_event_trigger_ddl_commands()
    WHERE command_tag IN ('CREATE TABLE', 'CREATE TABLE AS', 'SELECT INTO')
      AND object_type IN ('table','partitioned table')
  LOOP
     IF cmd.schema_name IS NOT NULL AND cmd.schema_name IN ('public') AND cmd.schema_name NOT IN ('pg_catalog','information_schema') AND cmd.schema_name NOT LIKE 'pg_toast%' AND cmd.schema_name NOT LIKE 'pg_temp%' THEN
      BEGIN
        EXECUTE format('alter table if exists %s enable row level security', cmd.object_identity);
        RAISE LOG 'rls_auto_enable: enabled RLS on %', cmd.object_identity;
      EXCEPTION
        WHEN OTHERS THEN
          RAISE LOG 'rls_auto_enable: failed to enable RLS on %', cmd.object_identity;
      END;
     ELSE
        RAISE LOG 'rls_auto_enable: skip % (either system schema or not in enforced list: %.)', cmd.object_identity, cmd.schema_name;
     END IF;
  END LOOP;
END;
$function$
